# ==================== BOT ENGINE ====================
def start_bot(config):
    uid = config["uid"]
    print(f"🚀 Starting bot for UID: {uid}")

    def on_open(ws):
        print(f"✅ Bot {uid} connected.")
        ws.send(FRAME_ACTIVE, websocket.ABNF.OPCODE_BINARY)
        time.sleep(0.3)
        join_frame = bytes.fromhex(config["join_frame_hex"].replace(" ", "").replace("\n", ""))
        ws.send(join_frame, websocket.ABNF.OPCODE_BINARY)
        print(f"🚀 Bot {uid} sent Channel.Enter.")
        time.sleep(0.3)
        ws.send(FRAME_ACTIVE, websocket.ABNF.OPCODE_BINARY)
        print(f"✅ Bot {uid} is ONLINE in the room!")

        def heartbeat():
            idx = 0
            while True:
                time.sleep(20)
                try:
                    ws.send(HEARTBEAT_FRAMES[idx % len(HEARTBEAT_FRAMES)], websocket.ABNF.OPCODE_BINARY)
                    idx += 1
                except:
                    break
        threading.Thread(target=heartbeat, daemon=True).start()

    def on_ping(ws, data):
        ws.send(data, websocket.ABNF.OPCODE_PONG)

    def on_error(ws, err):
        print(f"⚠️ Bot {uid} Error: {err}")

    def on_close(ws, a, b):
        print(f"❌ Bot {uid} disconnected. Reconnecting in 5s...")
        time.sleep(5)
        start_bot(config)

    ws_url = f"wss://i-875.olaparty.com/ikxd_cproxy?token={uid}"
    headers = {
        "X-Auth-Token": config["auth_token"],
        "X-DeviceId": config["device_id"],
        "X-DeviceType": "Google Pixel 4",
        "X-App-Name": "olaparty",
        "X-OsType": "android",
        "X-CpuArch": "aarch64",
        "X-App-Channel": "official",
        "X-Sdk-Ver": "30",
        "X-SimCIso": "in",
        "X-Client-Net": "1",
        "X-BuildCode": "3185",
        "X-App-LastVer": "",
        "X-Apk-Abi": "abi64",
        "X-Lang": "en_in",
        "X-App-Ver": "52303",
        "X-App-Real-Ver": "52303",
        "X-Os-Ver": "11",
        "X-Pcid": "1152921504624773252",
        "X-Request-WsId": str(int(time.time()*1000)),
        "X-Last-Seqid": "0",
        "Origin": "wss://i-875.olaparty.com",
        "User-Agent": "com.live.party/3185 (Linux; U; Android 11; en_IN; Pixel 4; Build/RD2A.211001.002; Cronet/93.0.4533.0)"
    }
    ws = websocket.WebSocketApp(ws_url, header=headers, on_open=on_open,
                                on_ping=on_ping, on_error=on_error, on_close=on_close)
    ws.run_forever(ping_interval=20, ping_timeout=10)

